<script setup lang="ts">
import {ref,computed,watch,onMounted,onUnmounted} from 'vue'
import {Heart,Utensils,ShowerHead,Moon,Home,Gamepad2,Coins,Trophy,ArrowLeft,RefreshCw,Shirt,Sparkles,Check,ChevronRight} from 'lucide-vue-next'
import VirtualDog from './DogSprite.vue'
import GameViewport from './GameViewport.vue'
import WeddingClock from './WeddingClock.vue'
import InstallGame from './InstallGame.vue'
import PetShop from './PetShop.vue'
import {emptyShop} from '../lib/shop'
import PetArcade from './PetGames.vue'
import {db,fail,friendly} from '../lib/supabase'
import {user,profile} from '../lib/session'
import {newPet,type PetAction} from '../lib/pet'
const props=defineProps<{dogName:string;weddingDate?:string;couple?:string}>(),emit=defineEmits<{login:[];close:[]}>()
type Room='home'|'kitchen'|'bath'|'garden'|'bedroom'|'wardrobe'
const shop=ref(emptyShop()),activeGame=ref(false)
const room=ref<Room>('home'),pet=ref(newPet()),busy=ref(false),loading=ref(false),feedback=ref(''),error=ref(''),animation=ref(''),showRank=ref(false),ranks=ref<{alias:string;xp:number;care_count:number}[]>([]),reward=ref(''),cooldown=ref(0)
let cooldownTimer:ReturnType<typeof setInterval>|undefined,animationTimer:ReturnType<typeof setTimeout>|undefined,refreshTimer:ReturnType<typeof setInterval>|undefined
let version=0
const saved=computed(()=>!!user.value&&profile.value?.id===user.value.id),level=computed(()=>Math.floor(pet.value.xp/100)+1),levelProgress=computed(()=>pet.value.xp%100)
const petName=computed(()=>props.dogName==='Nuestro compañero'?'Tu compi de cuatro patas':props.dogName)
const rooms=[{id:'home' as Room,label:'Mimos',icon:Home},{id:'kitchen' as Room,label:'Comida',icon:Utensils},{id:'bath' as Room,label:'Baño',icon:ShowerHead},{id:'garden' as Room,label:'Juegos',icon:Gamepad2},{id:'bedroom' as Room,label:'Sueño',icon:Moon},{id:'wardrobe' as Room,label:'Armario',icon:Shirt}]
const stats=computed(()=>[{label:'Barriguita',value:pet.value.hunger,icon:Utensils,color:'peach'},{label:'Limpieza',value:pet.value.hygiene,icon:ShowerHead,color:'blue'},{label:'Energía',value:pet.value.energy,icon:Moon,color:'purple'},{label:'Felicidad',value:pet.value.happiness,icon:Heart,color:'pink'}])
const speech=computed(()=>{if(feedback.value)return feedback.value;if(pet.value.sleeping)return 'Zzz… soñando con la boda';if(pet.value.hunger<25)return '¿Me das algo rico?';if(pet.value.energy<20)return 'Me vendría bien una siesta…';if(pet.value.hygiene<35)return 'Creo que necesito un bañito';return {home:'¡Has vuelto! ¿Me das un mimo?',kitchen:'¿Qué hay hoy de comer?',bath:'¡Que empiecen las burbujas!',garden:'¿Volamos juntos?',bedroom:'Un ratito de descanso nos viene bien.',wardrobe:'¿Qué me pongo para la boda?'}[room.value]})
async function load(){const seq=++version;if(!saved.value){pet.value=newPet();shop.value=emptyShop();activeGame.value=false;return}loading.value=true;try{const {data,error:e}=await db.rpc('wedding_pet_action',{action:'visit'});fail(e);if(seq===version)pet.value=data;const {data:wardrobe,error:we}=await db.rpc('wedding_pet_shop',{action:'visit'});fail(we);if(seq===version)shop.value=wardrobe}catch(e){error.value=friendly(e)}finally{if(seq===version)loading.value=false}}
async function shopAction(action:string,item=''){if(!saved.value||busy.value)return;busy.value=true;error.value='';const seq=version;try{const {data,error:e}=await db.rpc('wedding_pet_shop',{action,item});fail(e);if(seq!==version)return;shop.value=data;await load()}catch(e){error.value=friendly(e)}finally{busy.value=false}}
async function loadRanks(){if(!saved.value)return;const {data,error:e}=await db.rpc('wedding_pet_leaderboard');if(e){error.value=friendly(e);return}ranks.value=data??[]}
async function act(action:PetAction){if(!saved.value||busy.value||cooldown.value)return;error.value='';busy.value=true;const oldXp=pet.value.xp,oldCoins=pet.value.coins;const seq=version;try{
 if(saved.value){const {data,error:e}=await db.rpc('wedding_pet_action',{action});fail(e);if(seq!==version)return;pet.value=data}
 animation.value=['feed','apple','bone'].includes(action)?'eating':action==='wash'?'washing':action==='play'?'playing':action==='pet'?'petting':''
 feedback.value=({feed:'Ñam… ¡qué rico!',apple:'¡Una manzanita para mi barriguita!',bone:'Este huesito es lo más.',wash:'¡Limpito y listo para los abrazos!',play:'¡La tengo! Otra, otra…',pet:'Tú sí que sabes dar mimos.',sleep:'Buenas noches… zzz',wake:'¡Buenos días! ¿Qué hacemos hoy?'} as Partial<Record<PetAction,string>>)[action]??''
 reward.value=pet.value.xp>oldXp?`+${pet.value.xp-oldXp} XP${pet.value.coins>oldCoins?' · +'+(pet.value.coins-oldCoins)+' monedas':''}`:''
 clearTimeout(animationTimer);animationTimer=setTimeout(()=>{animation.value='';reward.value='';feedback.value=''},2400)
 cooldown.value=4;clearInterval(cooldownTimer);cooldownTimer=setInterval(()=>{cooldown.value=Math.max(0,cooldown.value-1);if(!cooldown.value)clearInterval(cooldownTimer)},1000)
 }catch(e){error.value=friendly(e)}finally{busy.value=false}}
function setRoom(value:Room){room.value=value;feedback.value='';error.value=''}
async function ranking(){showRank.value=!showRank.value;if(showRank.value)await loadRanks()}
watch(()=>[user.value?.id,!!profile.value],()=>{void load()})
onMounted(()=>{void load();refreshTimer=setInterval(()=>{if(saved.value&&!busy.value&&!document.hidden)void load()},30000)})
onUnmounted(()=>{version++;clearInterval(refreshTimer);clearInterval(cooldownTimer);clearTimeout(animationTimer)})
</script>
<template><GameViewport><div v-if="!saved" class="pet-game pet-login-gate"><VirtualDog/><h3>Tu perrito te está esperando</h3><p>{{user?'Completa tu perfil para cuidar al perrito y ganar recompensas.':'Entra con tu cuenta para cuidar al perrito, jugar y guardar tus monedas y experiencia.'}}</p><a v-if="user" href="#mi-invitacion" class="btn olive" @click="emit('close')">Completar mi perfil</a><button v-else class="btn olive" @click="emit('login')">Entrar con mi cuenta</button><button class="game-app-back text-link" @click="emit('close')">Volver a la invitación</button><InstallGame/></div><div v-else class="pet-game" :class="['room-'+room,'theme-'+shop.style.theme,{'playing-flight':activeGame}]"><header class="pet-topbar"><button class="pet-icon-button" @click="emit('close')" aria-label="Cerrar el juego"><ArrowLeft :size="20"/></button><div class="pet-game-title"><span>UN COMPI PARA CUIDAR</span><h3>{{petName}}</h3></div><div class="pet-wallet"><Coins :size="19"/><b>{{pet.coins}}</b></div></header><div class="pet-level"><span class="level-badge">{{level}}</span><div><div class="level-copy"><b>Nivel {{level}} · {{level<3?'Amigos inseparables':level<6?'Un gran cuidador':'Familia de cuatro patas'}}</b><span>{{levelProgress}} / 100 XP</span></div><div class="level-track"><span :style="{width:levelProgress+'%'}"></span></div></div><button class="pet-icon-button" aria-label="Ver clasificación" @click="ranking"><Trophy :size="20"/></button></div><div class="pet-needs"><button v-for="(s,i) in stats" :key="s.label" :class="s.color" @click="setRoom((['kitchen','bath','bedroom','home'] as Room[])[i]!)" :aria-label="s.label+' '+s.value+' de 100'"><span class="need-icon"><component :is="s.icon" :size="18"/></span><span><b>{{s.label}}</b><span class="need-track"><i :style="{width:s.value+'%'}"></i></span></span><strong>{{s.value}}</strong></button></div><div class="pet-room" :class="[room,{night:pet.sleeping},animation]"><div class="room-wall"><div class="room-window"><span></span><span></span><i></i><b>{{pet.sleeping?'☾':'☀'}}</b></div><div v-if="room==='home'||room==='bedroom'" class="room-frame"><Heart :size="25"/><span>L & J</span></div><div v-if="room==='kitchen'" class="kitchen-shelf"><span>🥕</span><span>🥣</span><span>🍎</span></div><div v-if="room==='bath'" class="bath-shelf"><span>🧴</span><span>🧽</span><span>🌿</span></div><div v-if="room==='garden'" class="garden-cloud cloud-one"></div><div v-if="room==='garden'" class="garden-cloud cloud-two"></div><div v-if="pet.sleeping" class="sleep-stars">✦ <span>✧</span> ✦</div></div><WeddingClock :date="weddingDate" :couple="couple"/><div class="room-floor"><div class="pet-rug"></div><span v-if="room==='garden'" class="garden-flowers">✿ <i>✿</i> ✿</span></div><div class="pet-speech" role="status">{{speech}}</div><button class="pet-character" :disabled="busy||!!cooldown||pet.sleeping" @click="act('pet')" aria-label="Acariciar al perrito"><VirtualDog :mood="animation" :sleeping="pet.sleeping" :dirty="pet.hygiene<40" :accessory="shop.style.accessory"/></button><div v-if="room==='bath'" class="pet-bathtub"><span></span><i></i></div><div v-if="room==='kitchen'" class="pet-bowl"><span>COMPI</span><i v-if="animation==='eating'">● ● ●</i></div><div v-if="room==='bedroom'" class="pet-bed"></div><div v-if="animation==='washing'" class="pet-bubbles"><i v-for="n in 9" :key="n" :style="{'--n':n}"></i></div><div v-if="animation==='petting'" class="floating-hearts"><span v-for="n in 5" :key="n" :style="{'--n':n}">♥</span></div><div v-if="animation==='playing'" class="pet-ball">●</div><div v-if="pet.sleeping" class="pet-zzz">z <span>Z</span> z</div><div v-if="reward" class="pet-reward" role="status"><Sparkles :size="17"/>{{reward}}</div></div><PetArcade v-if="room==='garden'" :disabled="pet.sleeping||busy" :accessory="shop.style.accessory" @active="activeGame=$event" @updated="load"/><PetShop v-else-if="room==='wardrobe'" :shop="shop" :coins="pet.coins" :level="level" :busy="busy||loading" @action="shopAction"/><div v-else class="pet-action-area"><template v-if="pet.sleeping"><button class="pet-action sleep-action" :disabled="busy||!!cooldown" @click="act('wake')"><span class="action-emoji">☀️</span><span><b>¡A despertar!</b><small>Su energía se recupera mientras duerme</small></span></button></template><template v-else-if="room==='kitchen'"><button v-for="food in [{action:'feed',emoji:'🥣',name:'Su comida',cost:6},{action:'apple',emoji:'🍎',name:'Manzanita',cost:10},{action:'bone',emoji:'🦴',name:'Un premio',cost:18}]" :key="food.action" class="pet-food" :disabled="busy||!!cooldown||pet.coins<food.cost" @click="act(food.action as PetAction)"><span>{{food.emoji}}</span><b>{{food.name}}</b><small><Coins :size="12"/>{{food.cost}}</small></button></template><template v-else><button class="pet-action" :class="room" :disabled="busy||!!cooldown" @click="act(room==='home'?'pet':room==='bath'?'wash':'sleep')"><span class="action-emoji">{{room==='home'?'💕':room==='bath'?'🫧':'🌙'}}</span><span><b>{{busy?'Un momentito…':cooldown?'¡Está disfrutando! '+cooldown+'s':room==='home'?'Darle un mimo':room==='bath'?'Un baño de burbujas':'Arropar y dormir'}}</b><small>{{room==='home'?'+15 felicidad · +3 XP':room==='bath'?'+35 limpieza · +8 XP':'Recupera energía incluso cuando sales'}}</small></span><ChevronRight :size="20"/></button></template></div><div v-if="room==='kitchen'&&pet.hunger<25&&!pet.sleeping" class="pet-world-snack"><button :disabled="busy" @click="shopAction('snack')">🥣 Cuenco de ayuda gratis · cada 6 h</button></div><p v-if="error" class="pet-error" role="alert">{{error}}</p><nav class="pet-dock" aria-label="Habitaciones del perrito"><button v-for="r in rooms" :key="r.id" :class="{selected:room===r.id}" @click="setRoom(r.id)" :aria-pressed="room===r.id"><component :is="r.icon" :size="22"/><span>{{r.label}}</span><i v-if="room===r.id"></i></button></nav><div class="pet-save-status"><span v-if="loading"><RefreshCw :size="13"/> Actualizando cuidados…</span><span v-else-if="saved"><Check :size="13"/> Tu compi se guarda en tu cuenta</span><button v-else @click="emit('login')">Entra para jugar <ChevronRight :size="13"/></button></div><div v-if="user&&!profile" class="pet-error">Completa tu perfil en Mi invitación para empezar a guardar el progreso.</div><InstallGame/><section v-if="showRank" class="pet-ranking"><h4><Trophy :size="20"/> Los mejores cuidadores</h4><p v-if="!saved">Entra y completa tu perfil para guardar cuidados y ver la clasificación.</p><p v-else-if="!ranks.length">El primer puesto te está esperando. Activa la clasificación en tu perfil para aparecer con tu alias.</p><ol v-else><li v-for="(r,i) in ranks" :key="i"><span class="rank-position">{{i+1}}</span><div><b>{{r.alias}}</b><small>{{r.care_count}} cuidados con cariño</small></div><strong>{{r.xp}} XP</strong></li></ol><p class="small">Solo se muestra el alias de quienes eligen participar.</p></section></div></GameViewport></template>
